/** Tarih biçimi. TR ay adları sabit (dil paketi bağımsız); diğer diller WP yereline göre. */
function gsx_date(int $ts, string $fmt = 'long'): string {
    if (gsx_lang() === 'tr') {
        $m = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];
        $ms = ['', 'Oca', 'Şub', 'Mar', 'Nis', 'May', 'Haz', 'Tem', 'Ağu', 'Eyl', 'Eki', 'Kas', 'Ara'];
        $n = (int) wp_date('n', $ts);
        return wp_date('j', $ts) . ' ' . ($fmt === 'short' ? $ms[$n] : $m[$n] . ' ' . wp_date('Y', $ts));
    }
    return wp_date($fmt === 'short' ? 'j M' : 'j F Y', $ts);
}
